#include "v34_phase4.h"
#include <string.h>
static bool prepare_mp(v34_phase4*p,bool ack){p->mp.acknowledge=ack;p->index=0;return v34_mp0_encode(&p->mp,p->mp_frame);}
bool v34_phase4_init(v34_phase4*p,bool call,const v34_scrambler*s,unsigned r,const v34_mp0*mp){if(!p||!s||!mp||r>3)return false;memset(p,0,sizeof(*p));p->state=V34_P4_J_PRIME;p->scrambler=*s;p->rotation=r;p->mp=*mp;p->call_modem=call;return true;}
bool v34_phase4_next(v34_phase4*p,uint8_t*phase){if(!p||!phase||p->state==V34_P4_COMPLETE)return false;for(;;){switch(p->state){case V34_P4_J_PRIME:if(v34_j_prime4_phase(&p->scrambler,&p->index,&p->rotation,phase))return true;p->state=V34_P4_TRN;p->index=0;v34_scrambler_init(&p->scrambler,p->call_modem);continue;case V34_P4_TRN:if(p->index<512){p->index++;if(!v34_trn4_phase(&p->scrambler,phase))return false;p->rotation=((12u-*phase)%12u)/3u;return true;}p->state=V34_P4_MP;if(!prepare_mp(p,false))return false;continue;case V34_P4_MP:if(v34_packed_bits4_phase(&p->scrambler,p->mp_frame,V34_MP0_BITS,&p->index,&p->rotation,phase))return true;p->state=V34_P4_MP_PRIME;if(!prepare_mp(p,true))return false;continue;case V34_P4_MP_PRIME:if(v34_packed_bits4_phase(&p->scrambler,p->mp_frame,V34_MP0_BITS,&p->index,&p->rotation,phase))return true;p->state=V34_P4_E;p->index=0;continue;case V34_P4_E:if(v34_e4_phase(&p->scrambler,&p->index,&p->rotation,phase))return true;p->state=V34_P4_COMPLETE;return false;case V34_P4_COMPLETE:return false;}}}
